<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesListRef;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesUidVO;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesRoleVO;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesVersionVO;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesItem;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\Accessor\UserRoleAssignmentRolesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserRoleAssignmentRolesAccessor trait.
 *
 * Covers null default, string/VO assignment via withRoles,
 * getRoles/roles accessors, and isRolesChanged with/without original.
 */
class UserRoleAssignmentRolesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRoles creates a new instance with the Roles set
     * from a string value, and getRoles returns the primitive string.
     */
    public function testWithRolesFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserRoleAssignmentRolesAccessorUnitTest();

        // Act
        $result = $holder->withRoles(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )), $result->getRoles());
    }
    /**
     * Asserts that withroles has access to the value object
     * from a string value, and getRoles returns the primitive string.
     */
    public function testWithRolesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserRoleAssignmentRolesAccessorUnitTest();

        // Act
        $result = $holder->withRoles(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )), $result->roles()->value());
    }
    public function testChangedRoles(): void
    {
        // Arrange
        $holder = new ImplWithUserRoleAssignmentRolesAccessorUnitTest()->withRoles(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )));
        $original = $holder->withRoles(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )));
        $same = $holder->withRoles(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )));
        $modified = $holder->withRoles(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('other'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('other')),
            UserRoleAssignmentRolesVersionVO::from(2)
        )));

        // Act
        $withSame = $original->isRolesChanged($same);
        $withDiferent = $original->isRolesChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserRoleAssignmentRolesAccessorUnitTest
{
    use UserRoleAssignmentRolesAccessor;
}
